import pytest
import json
from pathlib import Path
from validator import SwaggerSchemaValidator

# Load the API specification
api_spec_path = "api.json"
validator = SwaggerSchemaValidator(api_spec_path)

# Load test data from JSON file
_here = Path(__file__).resolve().parent
_endpoint_data_path = _here / "pet.json"

def _load_json_file(file_path):
    with open(file_path, 'r') as file:
        return json.load(file)

_ENDPOINT_DATA = _load_json_file(_endpoint_data_path)
_PARAM_CASES = _ENDPOINT_DATA
_PARAM_IDS = [case['scenario'] for case in _ENDPOINT_DATA]

@pytest.mark.parametrize("scenario_case", _PARAM_CASES, ids=_PARAM_IDS)
def test_post_pet(api_client, config_test_data, scenario_case):
    """
    Test POST /pet endpoint with different scenarios.
    """

    # Merge default test data with scenario specific data
    test_data = config_test_data.copy()
    test_data.update(scenario_case)

    # Extract necessary data for request
    pet_data = {
        "name": test_data.get("name"),
        "photoUrls": test_data.get("photoUrls"),
    }

    if 'category' in test_data:
        pet_data['category'] = test_data['category']
    if 'tags' in test_data:
        pet_data['tags'] = test_data['tags']
    if 'status' in test_data:
        pet_data['status'] = test_data['status']

    # Validate request before sending
    validator.validate_json(pet_data, "Pet")

    # Make API call
    response = api_client.post("/pet", data=pet_data)

    # Validate response schema
    validation_result = validator.validate_schema_by_response(
        "/pet", "post", str(test_data['statusCode']), response
    )
    assert validation_result['valid'], validation_result['message']

    # Assert status code
    assert response.status_code == test_data['statusCode']

    # Additional response checks
    if response.status_code == 200:
        response_data = response.json()
        assert response_data['name'] == pet_data['name']
        assert response_data['photoUrls'] == pet_data['photoUrls']

@pytest.mark.parametrize("auth_type", ["valid", "invalid", "missing"])
def test_post_pet_auth(api_client, config_test_data, auth_type):
    """
    Test POST /pet endpoint for authentication scenarios.
    """
    # Prepare pet data
    pet_data = {
        "name": "doggie",
        "photoUrls": ["http://example.com/photo1.jpg"]
    }

    # Set authentication based on auth_type
    if auth_type == "valid":
        api_client.session.headers.update({"Authorization": f"Bearer {config_test_data['petstore_auth']}"})
    elif auth_type == "invalid":
        api_client.session.headers.update({"Authorization": "Bearer invalid_token"})
    else:
        api_client.session.headers.pop("Authorization", None)

    # Make API call
    response = api_client.post("/pet", data=pet_data)

    # Validate response schema based on auth_type
    if auth_type == "valid":
        assert response.status_code == 200
    elif auth_type == "invalid":
        assert response.status_code == 401
    else:
        assert response.status_code == 401

    # Validate response schema
    validation_result = validator.validate_schema_by_response(
        "/pet", "post", str(response.status_code), response
    )
    assert validation_result['valid'], validation_result['message']
